def english_pool(year):
    """60 questions: 50 std + 2 passages x 5 questions. Std sets are disjoint across years:
    one master pool is shuffled once and dealt in 50-question blocks."""
    master = english_std_pool(2020)
    rng = random.Random("eng-master")
    rng.shuffle(master)
    chunk = master[(year - 2020) * 50:(year - 2020) * 50 + 50]
    out = []
    for q in chunk:
        q = dict(q)
        q["source"] = q["source"].replace("official 2020 paper", f"official {year} paper")
        out.append(q)
    # passages: 2 per year, disjoint across years (8 passages / 4 years)
    idx = (year - 2020) * 2
    for title, content, qs in PASSAGES[idx:idx + 2]:
        sub = []
        for q, c, ds, e, t in qs:
            sub.append(mk(q, c, ds, e, year, t))
        out.append({"type": "passage", "content": f"<b>{title}</b><br><br>{content}",
                    "questions": sub,
                    "practice": True,
                    "source": f"MyStudy Practice Set \u2014 modelled on the WAEC syllabus for this subject, not the official {year} paper | Topic: Comprehension | Original passage written for this practice set; syllabus: WAEC syllabus (waecsyllabus.com) and JAMB syllabus (ibass.jamb.gov.ng)"})
    return out

